'use strict';
// Музыка Акта II «Вечная Гроза» (Suno). Хранится как base64, чтобы работало и при открытии файла напрямую.
const MUSIC_B64 = '';

// Две раздельные дорожки. 'dark' — только Акт I «Вечный Мрак», 'storm' — только Акт II «Вечная Гроза».
// Какая играет, решает wantMusic() в game.js: он возвращает id дорожки или null; чужая дорожка при этом глушится и останавливается.
// Бесшовная петля: хвост (затухание) накладывается на начало (нарастание) на xf секунд, поэтому стыка и щелчка нет.
const Music = {
  tr: {
    dark:  { b64: () => MUSIC_DARK_B64, xf: 4.5, vol: 0.55 },
    storm: { b64: () => MUSIC_B64,      xf: 3,   vol: 0.5 },
  },
  want: null, last: 0,
  playing() { for (const k in this.tr) if (this.tr[k].src) return k; return null; },
  decode(id) {
    const T = this.tr[id];
    if (T.buf || T.loading || T.failed || !Sfx.ctx) return;
    T.loading = true;
    try {
      const bin = atob(T.b64()), u = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
      const ok = b => { T.buf = this.loopBuf(b, T.xf); T.loading = false; }, bad = () => { T.loading = false; T.failed = true; };
      const p = Sfx.ctx.decodeAudioData(u.buffer, ok, bad); if (p && p.catch) p.catch(bad);
    } catch (e) { T.loading = false; T.failed = true; }
  },
  loopBuf(b, sec) {
    const X = Math.floor(b.sampleRate * sec), N = b.length, M = N - X, out = Sfx.ctx.createBuffer(b.numberOfChannels, M, b.sampleRate);
    for (let ch = 0; ch < b.numberOfChannels; ch++) {
      const a = b.getChannelData(ch), o = out.getChannelData(ch);
      for (let i = 0; i < M; i++) o[i] = i < X ? a[N - X + i] + a[i] : a[i];
    }
    return out;
  },
  // вызывается каждый кадр: id — дорожка, которая должна играть сейчас (или null)
  update(id) {
    const now = performance.now(), dt = Math.min(0.1, (now - (this.last || now)) / 1000); this.last = now;
    this.want = id || null;
    if (!Sfx.ctx) return;
    Sfx.noDrone = !!id;            // пока играет музыка, низкий гул молчит
    if (id && Sfx.drone) Sfx.stopDrone();
    if (id) this.decode(id);
    const ctx = Sfx.ctx;
    for (const k in this.tr) {
      const T = this.tr[k], on = k === id;
      if (on && T.buf && !T.src) {
        T.gain = ctx.createGain(); T.gain.gain.value = 0.0001; T.gain.connect(ctx.destination);
        T.src = ctx.createBufferSource(); T.src.buffer = T.buf; T.src.loop = true; T.src.connect(T.gain); T.src.start(); T.idle = 0;
      }
      if (!T.src) continue;
      const target = on && Sfx.on ? T.vol : 0;
      T.gain.gain.setTargetAtTime(Math.max(target, 0.0001), ctx.currentTime, target ? 0.8 : 0.35);
      T.idle = target ? 0 : (T.idle || 0) + dt;
      if (T.idle > 3) { try { T.src.stop(); } catch (e) { /* уже остановлен */ } T.src.disconnect(); T.gain.disconnect(); T.src = null; T.gain = null; }
    }
  },
};
